-- Fresh PostgreSQL baseline, equivalent to the current SQL Server V17 application model.
-- SQL Server migrations and their history are intentionally not executed on PostgreSQL.
create table activity_logs (id bigint generated by default as identity, target_id bigint, timestamp timestamp(6), user_id bigint not null, action varchar(50) not null, target_type varchar(50), primary key (id));
create table cart_items (delivery_date date, quantity integer not null, rent_end_date date, rent_start_date date, cart_id bigint not null, id bigint generated by default as identity, product_id bigint not null, store_id bigint not null, order_type varchar(10) not null check ((order_type in ('BUY','RENT'))), greeting_message varchar(500), primary key (id));
create table carts (id bigint generated by default as identity, user_id bigint not null unique, primary key (id));
create table categories (is_deleted boolean, id bigint generated by default as identity, parent_id bigint, name varchar(100) not null unique, description text, primary key (id));
create table chat_access_audits (accessed_at timestamp(6) not null, admin_id bigint not null, before_message_id bigint, conversation_id bigint not null, id bigint generated by default as identity, primary key (id));
create table chat_conversations (created_at timestamp(6) not null, customer_id bigint not null, id bigint generated by default as identity, store_id bigint, updated_at timestamp(6) not null, kind varchar(16) not null, conversation_key varchar(100) not null, last_message varchar(2000), primary key (id), unique (conversation_key));
create table chat_messages (conversation_id bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, sender_id bigint not null, client_message_id varchar(36) not null, image_url varchar(500), content varchar(2000) not null, image_public_id varchar(255), primary key (id), unique (conversation_id, sender_id, client_message_id));
create table chat_product_contexts (product_price numeric(38,2) not null, id bigint generated by default as identity, message_id bigint not null unique, product_id bigint not null, product_name varchar(200) not null, product_image_url varchar(500), primary key (id));
create table commissions (cost numeric(38,2) not null, is_deleted boolean, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(32) not null unique, description varchar(3000), primary key (id));
create table customer_wallet_entries (amount numeric(18,2) not null, balance_after numeric(18,2) not null, created_at timestamp(6) not null, id bigint generated by default as identity, order_id bigint not null, user_id bigint not null, type varchar(12) not null, primary key (id), constraint UK_customer_wallet_order_type unique (order_id, type), check (amount > 0 and balance_after >= 0 and type in ('PAYMENT','REFUND')));
create table customer_wallets (balance numeric(18,2) not null, user_id bigint not null, version bigint not null, primary key (user_id), check (balance >= 0));
create table deliveries (is_active boolean not null, is_deleted boolean, price numeric(38,2) not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), phone varchar(50), name varchar(100) not null unique, vehicle_type varchar(100), description varchar(1000), coverage_area varchar(255), primary key (id));
create table inventory_transfer_requests (quantity integer not null, approved_by bigint, created_at timestamp(6), from_store_id bigint not null, id bigint generated by default as identity, product_id bigint not null, requested_by bigint, to_store_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED','COMPLETED'))), primary key (id));
create table jwt_refresh_tokens (consumed boolean not null, expires_at timestamp(6) with time zone not null, session_id varchar(36) not null, token_hash varchar(64) not null, primary key (token_hash));
create table jwt_sessions (revoked boolean not null, expires_at timestamp(6) with time zone not null, user_id bigint not null, id varchar(36) not null, credential_hash varchar(64) not null, primary key (id));
create table momo_payment_attempts (amount numeric(38,2) not null, completed boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, order_id bigint not null, environment varchar(16) not null, gateway_order_id varchar(100) not null unique, request_id varchar(100) not null unique, transaction_id varchar(100), extra_data varchar(1000) not null, order_info varchar(255) not null, primary key (id));
create table notifications (is_read boolean, created_at timestamp(6), id bigint generated by default as identity, related_order_id bigint, user_id bigint not null, type varchar(50), title varchar(200) not null, content text not null, primary key (id));
create table order_details (actual_return_date date, deposit_fee numeric(38,2), quantity integer not null, rent_end_date date, rent_start_date date, unit_price numeric(38,2) not null, id bigint generated by default as identity, order_id bigint not null, product_id bigint not null, order_type varchar(10) check ((order_type in ('BUY','RENT'))), primary key (id));
create table orders (commission_rate_snapshot numeric(9,4), delivery_date date, delivery_time time(0), discount_amount numeric(38,2), fine_amount numeric(38,2), funds_amount numeric(18,2), payment_expired boolean, shipping_fee numeric(18,2), total_amount numeric(38,2), total_deposit numeric(38,2), created_at timestamp(6), delivery_unit_id bigint, id bigint generated by default as identity, payment_expires_at timestamp(6), pickup_store_id bigint not null, return_store_id bigint, shipper_id bigint, user_id bigint not null, version bigint not null, voucher_id bigint, order_type varchar(10) not null check ((order_type in ('BUY','RENT'))), funds_status varchar(20) not null check ((funds_status in ('NONE','HELD','SETTLED','REFUNDED','REVIEW_REQUIRED'))), payment_method varchar(20), payment_status varchar(20), recipient_phone varchar(20), shipping_method varchar(20), status varchar(20) not null check ((status in ('PENDING','CONFIRMED','PREPARING','PICKED_UP','DELIVERING','DELIVERED','COMPLETED','CANCELLED','REFUND_REQUESTED','REFUNDED','RENTING','RETURNED','OVERDUE'))), recipient_name varchar(100), cancellation_reason varchar(500), greeting_message varchar(500), recipient_address varchar(255), primary key (id));
create table otp_verifications (failed_attempts integer not null, is_used boolean, code varchar(6) not null, created_at timestamp(6), expired_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, type varchar(30) not null check ((type in ('ACTIVATE_ACCOUNT','RESET_PASSWORD'))), primary key (id));
create table payments (amount numeric(38,2) not null, id bigint generated by default as identity, order_id bigint not null, paid_at timestamp(6), refunded_at timestamp(6), momo_environment varchar(16), method varchar(20) not null check ((method in ('COD','VNPAY','MOMO','MOMO_DEMO','WALLET_DEMO','CASH','BANK_TRANSFER'))), status varchar(20) not null check ((status in ('PENDING','SUCCESS','FAILED','REFUNDED'))), refund_method varchar(255), refund_note varchar(255), transaction_code varchar(255), primary key (id));
create table product_additional_categories (category_id bigint not null, product_id bigint not null, primary key (category_id, product_id));
create table product_images (is_main boolean, id bigint generated by default as identity, product_id bigint not null, cloudinary_public_id varchar(255), image_url varchar(255) not null, primary key (id));
create table product_style_values (product_id bigint not null, style_value_id bigint not null, primary key (product_id, style_value_id));
create table product_wishlists (created_at timestamp(6), id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, primary key (id), constraint uq_user_wishlist unique (user_id, product_id));
create table products (deposit_fee numeric(38,2) not null, import_price numeric(38,2) not null, is_active boolean not null, is_deleted boolean, is_selling boolean not null, price_buy numeric(38,2) not null, price_rent_per_day numeric(38,2) not null, promotional_price numeric(38,2), rating float(53), sold integer, view_count integer, category_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, store_id bigint, name varchar(200) not null, image_url varchar(500), description text, primary key (id));
create table promotions (discount_percentage integer not null, end_date date, start_date date, id bigint generated by default as identity, store_id bigint, apply_type varchar(10) check ((apply_type in ('BUY','RENT'))), name varchar(150) not null, primary key (id));
create table recently_viewed (id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, viewed_at timestamp(6), primary key (id));
create table reviews (rating integer not null, created_at timestamp(6), id bigint generated by default as identity, order_id bigint, product_id bigint not null, store_id bigint, updated_at timestamp(6), user_id bigint not null, image_url varchar(500), content varchar(1000) not null, primary key (id));
create table role_audit_logs (created_at timestamp(6) not null, id bigint generated by default as identity, performed_by_id bigint not null, store_id bigint, user_id bigint not null, action varchar(20) not null, role varchar(30) not null check ((role in ('STAFF','MANAGER','ADMIN','USER'))), reason varchar(500), primary key (id));
create table role_requests (assigned_store_id bigint, created_at timestamp(6) not null, id bigint generated by default as identity, reviewed_at timestamp(6), reviewed_by_id bigint, target_store_id bigint, user_id bigint not null, phone varchar(20), status varchar(30) not null check ((status in ('PENDING','APPROVED','REJECTED','CANCELLED'))), target_role varchar(30) not null, vehicle_type varchar(100), rejection_reason varchar(500), shop_address varchar(500), experience_note varchar(1000), contact_info varchar(255), shop_name varchar(255), work_area varchar(255), primary key (id));
create table shipping_tariffs (base_fee numeric(18,2) not null, bulky_surcharge numeric(18,2) not null, is_active boolean not null, is_deleted boolean not null, created_at timestamp(6), delivery_id bigint, id bigint generated by default as identity, store_id bigint, updated_at timestamp(6), estimated_time varchar(100), service_name varchar(100) not null, destination_area varchar(150) not null, note varchar(500), primary key (id));
create table store_inventories (is_deleted boolean not null, is_selling boolean not null, quantity integer not null, id bigint generated by default as identity, product_id bigint not null, store_id bigint not null, version bigint not null, primary key (id), unique (store_id, product_id));
create table store_levels (discount numeric(38,2) not null, is_deleted boolean, min_point integer not null unique, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(32) not null unique, primary key (id));
create table store_memberships (active boolean not null, id bigint generated by default as identity, joined_at timestamp(6), store_id bigint not null, user_id bigint not null, access_role varchar(16) not null, primary key (id), unique (store_id, user_id));
create table stores (e_wallet numeric(18,2), is_open boolean, latitude float(53), longitude float(53), pending_balance numeric(18,2) not null, point integer, rating float(53), status boolean, commission_id bigint, created_at timestamp(6), id bigint generated by default as identity, owner_id bigint, store_level_id bigint, version bigint not null, phone varchar(20), creation_request_key varchar(80), name varchar(150) not null, avatar varchar(500), cover varchar(500), bio varchar(1000), address varchar(255) not null, avatar_public_id varchar(255), cover_public_id varchar(255), featured_image_public_ids text, featured_images text, primary key (id));
create table style_values (is_deleted boolean, created_at timestamp(6), id bigint generated by default as identity, style_id bigint not null, updated_at timestamp(6), name varchar(32) not null, primary key (id));
create table styles (is_deleted boolean not null, category_id bigint, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(100) not null unique, primary key (id));
create table transactions (amount numeric(38,2) not null, earned_points integer, is_up boolean not null, created_at timestamp(6), id bigint generated by default as identity, order_id bigint, store_id bigint, user_id bigint, status varchar(20), wallet_bucket varchar(20) not null, type varchar(30), request_key varchar(80), description varchar(500), primary key (id));
create table user_addresses (is_default boolean not null, created_at timestamp(6), id bigint generated by default as identity, user_id bigint not null, phone varchar(20) not null, recipient_name varchar(100) not null, address_detail varchar(255) not null, primary key (id));
create table user_follow_store (created_at timestamp(6), id bigint generated by default as identity, store_id bigint not null, user_id bigint not null, primary key (id), constraint uq_user_follow_store unique (user_id, store_id));
create table user_levels (discount numeric(38,2) not null, is_deleted boolean, min_point integer not null unique, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(32) not null unique, primary key (id));
create table user_roles (user_id bigint not null, role varchar(30) not null check ((role in ('STAFF','MANAGER','ADMIN','USER'))), primary key (user_id, role));
create table users (account_disabled_by_admin boolean, created_date date, creation_time_known boolean, e_wallet numeric(18,2), is_active boolean, is_email_active boolean not null, point integer, retired_delivery_account boolean, created_at timestamp(6), id bigint generated by default as identity, otp_expiry timestamp(6), store_id bigint, user_level_id bigint, otp_code varchar(10), phone varchar(20), role varchar(20) not null check ((role in ('STAFF','MANAGER','ADMIN','USER','SHIPPER'))), username varchar(50) not null unique, email varchar(100) not null unique, full_name varchar(100) not null, cover varchar(500), address varchar(255), avatar_public_id varchar(255), avatar_url varchar(255), cover_public_id varchar(255), password varchar(255) not null, primary key (id));
create table vouchers (discount_value numeric(38,2) not null, end_date date not null, is_active boolean not null, max_discount_amount numeric(38,2), min_order_value numeric(38,2), quantity integer not null, start_date date not null, used_count integer not null, created_at timestamp(6), id bigint generated by default as identity, store_id bigint, discount_type varchar(20) not null, code varchar(50) not null unique, name varchar(150) not null, primary key (id));
create index idx_chat_audit_admin_time on chat_access_audits (admin_id, accessed_at);
create index idx_chat_audit_conversation_time on chat_access_audits (conversation_id, accessed_at);
create index idx_chat_messages_conversation_id on chat_messages (conversation_id, id);
create index IX_customer_wallet_history on customer_wallet_entries (user_id, id);
